      {/* seyircide avatar alkışlıyor */}
      <Person x={140} y={1560} s={0.6} belly={0.4} armL={medal > 0.5 ? [150, -40 + 30 * Math.sin(f / 3)] : [12, 0]} armR={medal > 0.5 ? [150, -40 - 30 * Math.sin(f / 3)] : [12, 0]} mouth={medal > 0.5 ? "grin" : "o"} lookY={-8} />
