  const armR: Arm = [interpolate(up * (1 - down), [0, 1], [PHONE_ARM[0], 160]), interpolate(up * (1 - down), [0, 1], [PHONE_ARM[1], -20])];
  const arrow = up * (1 - tw(f, w(3), w(4) + 4));
