      <Person x={A.x} y={A.y} s={A.s} belly={0.4} armL={[12, 0]} armR={armR} mouth={down > 0.5 ? "smile" : f > w(3) ? "grin" : "smile"} eyes={f >= w(9) && f < w(10) + 4 ? "closed" : "open"} lookY={12 * down}>
        {up * (1 - down) < 0.3 ? <PhoneInHand arm={armR} /> : null}
      </Person>
